import{Pt as e,Q as t,Wt as n,at as r,bt as i,g as a,it as o,lt as s,n as c,ot as l,st as u,tt as d,vt as f}from"./chunks/framework.fhiXEbOi.js";import{n as p}from"./chunks/theme.ByWjr53I.js";var m={class:`grid two`,"aria-label":`Documentation sections`},h=[`data-section`],g=[`href`],_=c(s({__name:`HomeSections`,setup(r){return(r,s)=>(f(),o(`div`,m,[(f(!0),o(t,null,i(n(p),t=>(f(),o(`section`,{key:t.id,class:`card home-section-card`,"data-section":t.id},[d(`h2`,null,[d(`a`,{href:n(a)(t.href)},e(t.label),9,g)]),d(`p`,null,e(t.summary),1)],8,h))),128))]))}}),[[`__scopeId`,`data-v-59043033`]]),v={class:`ported-guide`},y={id:`documentation`},b=JSON.parse(`{"title":"What is dapp32?","description":"Business contracts, a CAM root, an off-chain manifest, and a standard viewer.","frontmatter":{"title":"What is dapp32?","description":"Business contracts, a CAM root, an off-chain manifest, and a standard viewer.","outline":false},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),x=s({name:`index.md`,setup(e){return(e,t)=>(f(),o(`div`,null,[t[1]||=d(`h1`,{id:`what-is-dapp32`,tabindex:`-1`},[l(`What is dapp32? `),d(`a`,{class:`header-anchor`,href:`#what-is-dapp32`,"aria-label":`Permalink to “What is dapp32?”`},`​`)],-1),d(`div`,v,[t[0]||=r(`<p>A typical dapp32 application involves four distinct components, although only three are specific to the application.</p><table><thead><tr><th>Component</th><th>Location</th><th>Application-specific?</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>Business contracts</strong></td><td>On-chain</td><td>Yes</td><td>Implement business logic, maintain state, enforce permissions, and execute transactions.</td></tr><tr><td><strong>CAM root contract</strong></td><td>On-chain</td><td>Yes</td><td>Publishes a reference to the application&#39;s CAM and resolves named contract addresses.</td></tr><tr><td><strong>Contract Application Manifest (CAM)</strong></td><td>Off-chain</td><td>Yes</td><td>Describes the application&#39;s workflows, contract interactions, screens, forms, and actions.</td></tr><tr><td><strong>Standard viewer</strong></td><td>Off-chain</td><td>No</td><td>Interprets the CAM, renders the application, reads contract state, and prepares transactions.</td></tr></tbody></table><p>There is also an optional on-chain <strong>UI projection contract</strong>. For example, <code>CamEscrowUI</code> assembles contract state into information suitable for display. It does not define the interface or authorize transactions.</p><h2>The important distinctions</h2><p><strong>The CAM root does not define the UI.</strong> It identifies the application&#39;s contracts and publishes the location and digest of the CAM. It is an on-chain publication and discovery mechanism, not a web host.</p><p><strong>The CAM is not itself a smart contract.</strong> It consists of off-chain files, including:</p><ul><li><code>main.json</code>: workflows, routes, and contract reads and writes.</li><li><code>ui.json</code>: screens, controls, forms, and presentation definitions.</li><li>ABI and protocol resources: the interfaces and conventions needed to interpret those operations.</li></ul><p><strong>The viewer is not specific to the application.</strong> The same software interprets different CAMs. An autonomous agent can interpret a CAM without using the graphical viewer.</p><h2>How they fit together</h2><p><strong>Opening an application:</strong><br>Viewer → CAM root → CAM → contract reads → rendered interface.</p><p><strong>Executing an action:</strong><br>Interface → prepared transaction → wallet approval → business contract.</p><p>The business contracts remain authoritative throughout.</p><p>A dapp32 application therefore has three application-specific components: business contracts, a CAM root contract, and an off-chain CAM. The standard viewer is shared infrastructure. A developer can publish another application without writing a separate frontend for it.</p><p>This repository demonstrates the approach end to end with three applications: Pay-to-Play, Escrow, and Bike NFT.</p>`,14),d(`section`,y,[u(_)])])]))}});export{b as __pageData,x as default};